const query = $input.first().json.query || {};
const fileId = query.file_id || '';
const code = query.code || '';

if (!fileId || !code) {
  return [{ json: { valid: false, error: 'Parametres manquants (file_id ou code)' } }];
}

return [{ json: { valid: true, file_id: fileId, code: code } }];

const query = $('Extraire parametres').first().json;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const flashcards = JSON.parse(buffer.toString('utf-8'));

if (flashcards.code_suppression !== query.code) {
  return [{ json: { verified: false, error: 'Code de validation invalide' } }];
}

// T-SEC (2026-10-06) : un jeu Box-FONDA (type === "fonda") DOIT etre relu carte par
// carte via box-select avant publication - ce lien historique (validation en bloc)
// ne peut plus le publier. Condition en LISTE BLANCHE POSITIVE : on ne refuse QUE si
// type vaut EXACTEMENT "fonda" ET que revue_carte_par_carte n'est pas exactement
// true. Un champ absent, une valeur differente, ou un ancien jeu sans aucun des deux
// champs -> jamais refuse, publie comme avant (regle d'or : en cas de doute, laisser
// passer). Les jeux BOX ordinaires ne sont PAS concernes par ce controle.
if (flashcards.type === 'fonda' && flashcards.revue_carte_par_carte !== true) {
  return [{ json: {
    verified: false,
    error: 'Ce jeu Box-FONDA doit etre relu carte par carte via le lien de selection recu par email, pas valide en bloc depuis cet ancien lien.',
  } }];
}

return [{ json: {
  verified: true,
  id: flashcards.id,
  matiere: flashcards.matiere,
  niveau: flashcards.niveau,
  notion: flashcards.notion,
  prof_nom: flashcards.prof_nom,
  prof_email: flashcards.prof_email,
  nb_cartes: flashcards.nb_cartes || flashcards.cartes.length,
  date_creation: flashcards.date_creation,
  drive_file_id: query.file_id
} }];

const setData = $('Verifier code').first().json;

// Lire le catalogue existant
let catalogue;
try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  let parsed = JSON.parse(buffer.toString('utf-8'));
  if (typeof parsed === 'string') parsed = JSON.parse(parsed);
  if (typeof parsed === 'object' && Array.isArray(parsed.sets)) {
    catalogue = parsed;
  } else {
    catalogue = { last_updated: '', total_sets: 0, sets: [] };
  }
} catch (e) {
  catalogue = { last_updated: '', total_sets: 0, sets: [] };
}

// Verifier que le set n'est pas deja dans le catalogue
if (catalogue.sets.some(s => s.id === setData.id)) {
  return [{ json: { already_published: true, notion: setData.notion } }];
}

// Ajouter la nouvelle entree
catalogue.sets.push({
  id: setData.id,
  matiere: setData.matiere,
  niveau: setData.niveau,
  notion: setData.notion,
  prof_nom: setData.prof_nom,
  nb_cartes: setData.nb_cartes,
  date_creation: setData.date_creation,
  drive_file_id: setData.drive_file_id
});

catalogue.total_sets = catalogue.sets.length;
catalogue.last_updated = new Date().toISOString();

return [{ json: {
  catalogue_json: JSON.stringify(catalogue, null, 2),
  notion: setData.notion,
  already_published: false
} }];

const data = $('Verifier code').first().json;

function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// T-SEC (2026-10-06, 3e passe) : balayage complet de l'echappement HTML - email en
// emailType 'html', donc TOUT champ texte libre doit etre echappe ici aussi, pas
// seulement dans les pages de relecture. studentUrl echappe par uniformite (meme si
// data.id est de forme generee cote serveur).
const studentUrl = escapeHtml(`https://ericduchateau.github.io/box/?set=${data.id}`);

const emailHtml = `<div style="font-family:sans-serif;max-width:600px;margin:0 auto">
  <h2 style="color:#16a34a">&#9989; Vos fiches sont publiees et accessibles aux eleves !</h2>
  <p>
    <strong>Notion :</strong> ${escapeHtml(data.notion)}<br>
    <strong>Matiere :</strong> ${escapeHtml(data.matiere)} &mdash; ${escapeHtml(data.niveau)}<br>
    <strong>Nombre de fiches :</strong> ${data.nb_cartes}
  </p>
  <hr>
  <h3>&#128279; Lien direct a partager avec vos eleves :</h3>
  <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:16px;margin:16px 0">
    <p style="margin:0 0 8px 0;font-size:13px;color:#64748b">Copiez ce lien dans votre cahier de texte numerique :</p>
    <p style="margin:0 0 12px 0;background:white;border:1px solid #dbeafe;border-radius:4px;padding:10px;font-family:monospace;word-break:break-all;font-size:14px;font-weight:bold">${studentUrl}</p>
    <a href="${studentUrl}" style="color:#2563eb;font-size:14px">Ouvrir les fiches &rarr;</a>
  </div>
  <p style="color:#64748b;font-size:12px">Ce lien ouvrira directement le jeu de fiches <strong>${escapeHtml(data.notion)}</strong> pour vos eleves, sans passer par le catalogue.</p>
</div>`;

return [{ json: {
  prof_email: data.prof_email,
  notion: data.notion,
  nb_cartes: data.nb_cartes,
  email_html: emailHtml
} }];

const data = $('Verifier code').first().json;

function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// T-SEC (2026-10-06, 3e passe) : notion/studentUrl echappes - signale par la 3e
// critique Codex (page de l'ancien lien box-validate, oubliee dans la 1re passe
// d'echappement qui ne visait que box-select).
const studentUrl = escapeHtml('https://ericduchateau.github.io/box/?set=' + data.id);

const html = `<html>
<body style="font-family:sans-serif;text-align:center;padding:60px">
  <div style="max-width:540px;margin:0 auto">
    <h2 style="color:#16a34a">&#9989; Fiches publi\u00e9es !</h2>
    <p style="font-size:18px">Les fiches <strong>${escapeHtml(data.notion)}</strong> (${data.nb_cartes} fiches) sont maintenant accessibles aux \u00e9l\u00e8ves.</p>
    <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:16px;margin:24px 0;text-align:left">
      <p style="margin:0 0 8px 0;font-weight:bold;color:#1e40af">&#128279; Lien \u00e0 partager avec vos \u00e9l\u00e8ves :</p>
      <p style="margin:0 0 10px 0;background:white;border:1px solid #dbeafe;border-radius:4px;padding:10px;font-family:monospace;word-break:break-all;font-size:13px">${studentUrl}</p>
      <p style="margin:0;color:#16a34a;font-size:13px">&#128231; Ce lien vous a aussi \u00e9t\u00e9 envoy\u00e9 par email.</p>
    </div>
    <p style="margin-top:24px"><a href="https://ericduchateau.github.io/box/" style="color:#2563eb">Aller sur la page BOX &rarr;</a></p>
  </div>
</body>
</html>`;

return [{ json: { html } }];
